import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import { FiMapPin, FiPhone, FiUser, FiX } from 'react-icons/fi';

const ProductModal = ({ product, isOpen, onClose }) => {
    const { user } = useAuth();
    const [showContact, setShowContact] = useState(false);
    const [currentPhotoIndex, setCurrentPhotoIndex] = useState(0);
    const [currentProduct, setCurrentProduct] = useState(product);

    useEffect(() => {
        setCurrentProduct(product);
    }, [product]);

    useEffect(() => {
        if (isOpen && product?.id) {
            fetchProductData();
        }
    }, [isOpen, product?.id]);

    const fetchProductData = async () => {
        try {
            const response = await api.get(`/products/${product.id}`);
            if (response.data.success) {
                setCurrentProduct(response.data.product);
            }
        } catch (error) {
            console.error('Erro ao buscar produto:', error);
        }
    };

    useEffect(() => {
        const handleEsc = (e) => {
            if (e.key === 'Escape') onClose();
        };
        if (isOpen) {
            document.body.style.overflow = 'hidden';
            window.addEventListener('keydown', handleEsc);
        }
        return () => {
            document.body.style.overflow = 'unset';
            window.removeEventListener('keydown', handleEsc);
        };
    }, [isOpen, onClose]);

    if (!isOpen || !currentProduct) return null;

    const isOwner = user && currentProduct.sellerId === user.id;
    
    const getCategoryIcon = (category) => {
        const icons = { telemovel: '📱', laptop: '💻', console: '🎮', tablet: '📟' };
        return icons[category] || '📦';
    };

    const getContactMethodIcon = (method) => {
        if (method === 'whatsapp') return '💚 WhatsApp';
        if (method === 'call') return '📞 Ligação';
        return '💚 WhatsApp / 📞 Ligação';
    };

    const getConditionText = (condition) => {
        switch(condition) {
            case 'novo': return 'Novo';
            case 'semi-novo': return 'Semi-novo';
            case 'segunda-mao': return 'Segunda Mão';
            default: return condition || 'Semi-novo';
        }
    };

    const getConditionClass = (condition) => {
        switch(condition) {
            case 'novo': return 'bg-green-50 text-green-700';
            case 'semi-novo': return 'bg-yellow-50 text-yellow-700';
            case 'segunda-mao': return 'bg-stone-300 text-stone-800';
            default: return 'bg-gray-100 text-gray-600';
        }
    };

    const handleBackdropClick = (e) => {
        if (e.target === e.currentTarget) onClose();
    };

    return (
        <div 
            className="fixed inset-0 bg-black bg-opacity-50 backdrop-blur-sm flex items-center justify-center z-[1000] p-2 sm:p-4"
            onClick={handleBackdropClick}
        >
            <div className="bg-white rounded-2xl w-full max-w-[95%] sm:max-w-[90%] md:max-w-2xl max-h-[95vh] overflow-y-auto shadow-2xl">
                <div className="sticky top-0 bg-white border-b p-3 sm:p-4 flex justify-between items-center rounded-t-2xl">
                    <h2 className="text-base sm:text-lg font-semibold text-gray-800">Detalhes do Produto</h2>
                    <button onClick={onClose} className="p-1.5 sm:p-2 hover:bg-gray-100 rounded-full transition">
                        <FiX size={18} />
                    </button>
                </div>

                <div className="p-4 sm:p-5">
                    {/* Imagem Principal com borda */}
                    <div className="bg-gray-100 rounded-xl p-4 flex justify-center items-center mb-4 h-64 sm:h-80 md:h-96 border border-gray-200">
                        {currentProduct.photos && currentProduct.photos[0] ? (
                            <img 
                                src={`http://localhost:3001${currentProduct.photos[currentPhotoIndex]}`} 
                                alt={currentProduct.title} 
                                className="max-w-full max-h-full object-contain rounded-lg" 
                            />
                        ) : (
                            <div className="text-6xl">{getCategoryIcon(currentProduct.category)}</div>
                        )}
                    </div>

                    {/* Miniaturas com borda */}
                    {currentProduct.photos && currentProduct.photos.length > 1 && (
                        <div className="flex gap-2 mb-5 overflow-x-auto pb-2">
                            {currentProduct.photos.map((photo, idx) => (
                                <button
                                    key={idx}
                                    onClick={() => setCurrentPhotoIndex(idx)}
                                    className={`w-14 h-14 sm:w-16 sm:h-16 rounded-lg overflow-hidden flex-shrink-0 border-2 ${
                                        currentPhotoIndex === idx ? 'border-blue-500' : 'border-gray-300'
                                    }`}
                                >
                                    <img 
                                        src={`http://localhost:3001${photo}`} 
                                        alt={`Foto ${idx + 1}`} 
                                        className="w-full h-full object-cover" 
                                    />
                                </button>
                            ))}
                        </div>
                    )}

                    <h3 className="text-lg sm:text-xl font-bold text-gray-800 mb-1">{currentProduct.title}</h3>
                    
                    <div className="flex items-center gap-2 mb-3">
                        <span className={`px-2 py-1 rounded-full text-xs font-semibold ${getConditionClass(currentProduct.condition)}`}>
                            {getConditionText(currentProduct.condition)}
                        </span>
                        <span className="text-xs text-gray-400">{currentProduct.category}</span>
                    </div>

                    <p className="text-xl sm:text-2xl font-bold text-blue-600 mb-4">
                        {currentProduct.price.toLocaleString()} Kz
                    </p>

                    <div className="border-t border-gray-100 pt-4 mb-4">
                        <p className="text-gray-700 text-sm leading-relaxed">{currentProduct.description}</p>
                    </div>

                    <div className="space-y-2 mb-5 text-sm">
                        <div className="flex items-center text-gray-500">
                            <FiMapPin className="mr-2 text-gray-400" size={14} />
                            <span>{currentProduct.location}</span>
                        </div>
                        <div className="flex items-center text-gray-500">
                            <FiUser className="mr-2 text-gray-400" size={14} />
                            <span>{currentProduct.sellerName}</span>
                        </div>
                    </div>

                    {!isOwner && (
                        <>
                            {showContact ? (
                                <div className="bg-green-50 rounded-xl p-3 sm:p-4 border border-green-200">
                                    <p className="font-medium text-green-700 mb-1">{getContactMethodIcon(currentProduct.contactMethod)}</p>
                                    <p className="text-base sm:text-lg font-bold text-green-700">{currentProduct.contactNumber}</p>
                                    {currentProduct.contactHours && (
                                        <p className="text-xs text-green-600 mt-1">Horário: {currentProduct.contactHours}</p>
                                    )}
                                </div>
                            ) : (
                                <button
                                    onClick={() => {
                                        if (!user) {
                                            alert('Faça login para ver o contato');
                                            return;
                                        }
                                        setShowContact(true);
                                    }}
                                    className="w-full bg-blue-600 text-white py-2.5 rounded-lg font-medium hover:bg-blue-700 transition"
                                >
                                    Ver número do vendedor
                                </button>
                            )}
                        </>
                    )}

                    {isOwner && (
                        <div className="bg-blue-50 rounded-xl p-3 border border-blue-200">
                            <p className="text-blue-600 font-medium">📌 Este é seu anúncio</p>
                            <p className="text-xs text-blue-600 mt-1">
                                {getContactMethodIcon(currentProduct.contactMethod)}: {currentProduct.contactNumber}
                            </p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default ProductModal;
